//! Optional GPU backend for the `nungw` fused element-wise kernels, via wgpu and
//! WGSL compute shaders. Enabled by the `gpu` Cargo feature; off by default, so
//! ordinary builds, the wasm playground and CI are untouched.
//!
//! Precision on the GPU is **f32** (Metal and most consumer GPUs lack fast f64),
//! so results differ from the CPU f64 path in the low bits. The WGSL kernel is
//! generated by `library::program_to_wgsl` from the same fused RPN program the
//! CPU runs, so one fused expression maps to one compute dispatch.

use std::collections::HashMap;
use std::rc::Rc;
use std::sync::{Mutex, OnceLock};

use wgpu::util::DeviceExt;

struct Gpu {
    device: wgpu::Device,
    queue: wgpu::Queue,
    /// The tiled matmul pipeline, compiled once at init and reused every call
    /// (shader compilation is expensive, so it must not happen per call).
    matmul_pipeline: wgpu::ComputePipeline,
    /// A general GEMM that can transpose either operand (via `dims.w` flags),
    /// used for `matmul_ta` / `matmul_tb`. Naive but correct.
    matmul_t_pipeline: wgpu::ComputePipeline,
}

/// General f32 GEMM. `dims` = (rows, inner, cols, flags); flag bit0 transposes A,
/// bit1 transposes B. op(A) is rows×inner, op(B) is inner×cols, result rows×cols.
const MATMUL_T_WGSL: &str = "\
@group(0) @binding(0) var<storage, read> a: array<f32>;
@group(0) @binding(1) var<storage, read> b: array<f32>;
@group(0) @binding(2) var<storage, read_write> outp: array<f32>;
@group(0) @binding(3) var<uniform> dims: vec4<u32>;
@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
  let rows = dims.x;
  let inner = dims.y;
  let cols = dims.z;
  let r = gid.x;
  let c = gid.y;
  if (r >= rows || c >= cols) { return; }
  let ta = (dims.w & 1u) != 0u;
  let tb = (dims.w & 2u) != 0u;
  var acc = 0.0;
  for (var k = 0u; k < inner; k = k + 1u) {
    var av: f32;
    var bv: f32;
    if (ta) { av = a[k * rows + r]; } else { av = a[r * inner + k]; }
    if (tb) { bv = b[c * inner + k]; } else { bv = b[k * cols + c]; }
    acc = acc + av * bv;
  }
  outp[r * cols + c] = acc;
}
";

/// Tiled (16x16, shared-memory) f32 GEMM. `dims` = (rows, inner, cols).
const MATMUL_WGSL: &str = "\
@group(0) @binding(0) var<storage, read> a: array<f32>;
@group(0) @binding(1) var<storage, read> b: array<f32>;
@group(0) @binding(2) var<storage, read_write> outp: array<f32>;
@group(0) @binding(3) var<uniform> dims: vec4<u32>;
var<workgroup> tile_a: array<f32, 256>;
var<workgroup> tile_b: array<f32, 256>;
@compute @workgroup_size(16, 16)
fn main(@builtin(workgroup_id) wid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  let rows = dims.x;
  let inner = dims.y;
  let cols = dims.z;
  let row = wid.x * 16u + lid.x;
  let col = wid.y * 16u + lid.y;
  var acc = 0.0;
  let ntiles = (inner + 15u) / 16u;
  for (var t = 0u; t < ntiles; t = t + 1u) {
    let a_col = t * 16u + lid.y;
    let b_row = t * 16u + lid.x;
    if (row < rows && a_col < inner) { tile_a[lid.x * 16u + lid.y] = a[row * inner + a_col]; }
    else { tile_a[lid.x * 16u + lid.y] = 0.0; }
    if (col < cols && b_row < inner) { tile_b[lid.x * 16u + lid.y] = b[b_row * cols + col]; }
    else { tile_b[lid.x * 16u + lid.y] = 0.0; }
    workgroupBarrier();
    for (var k = 0u; k < 16u; k = k + 1u) {
      acc = acc + tile_a[lid.x * 16u + k] * tile_b[k * 16u + lid.y];
    }
    workgroupBarrier();
  }
  if (row < rows && col < cols) { outp[row * cols + col] = acc; }
}
";

/// The process-wide GPU context, initialized once. `None` if no usable adapter
/// or device could be obtained (the caller then stays on the CPU).
fn ctx() -> Option<&'static Gpu> {
    static CTX: OnceLock<Option<Gpu>> = OnceLock::new();
    CTX.get_or_init(|| {
        let instance = wgpu::Instance::default();
        let adapter =
            pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default())).ok()?;
        let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
            label: Some("globw-gpu"),
            ..Default::default()
        }))
        .ok()?;
        let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("globw-matmul"),
            source: wgpu::ShaderSource::Wgsl(MATMUL_WGSL.into()),
        });
        let matmul_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("globw-matmul"),
            layout: None,
            module: &module,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });
        let module_t = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("globw-matmul-t"),
            source: wgpu::ShaderSource::Wgsl(MATMUL_T_WGSL.into()),
        });
        let matmul_t_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("globw-matmul-t"),
            layout: None,
            module: &module_t,
            entry_point: Some("main"),
            compilation_options: Default::default(),
            cache: None,
        });
        Some(Gpu { device, queue, matmul_pipeline, matmul_t_pipeline })
    })
    .as_ref()
}

/// True if a usable GPU adapter/device was found.
pub fn available() -> bool {
    ctx().is_some()
}

/// Runs a transpiled element-wise WGSL kernel over f32 inputs (one storage
/// buffer per input, bound at 0..inputs.len(), output at inputs.len()), and
/// returns the f32 output of length `n`. `None` on any failure -> CPU fallback.
pub fn run_elementwise(wgsl: &str, inputs: &[Vec<f32>], n: usize) -> Option<Vec<f32>> {
    let gpu = ctx()?;
    let dev = &gpu.device;

    let module = dev.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("globw-fused"),
        source: wgpu::ShaderSource::Wgsl(wgsl.into()),
    });
    let pipeline = dev.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("globw-fused"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let bgl = pipeline.get_bind_group_layout(0);

    let in_bufs: Vec<wgpu::Buffer> = inputs
        .iter()
        .enumerate()
        .map(|(k, data)| {
            dev.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                label: Some(&format!("in{k}")),
                contents: bytemuck::cast_slice(data),
                usage: wgpu::BufferUsages::STORAGE,
            })
        })
        .collect();

    let out_size = (n * std::mem::size_of::<f32>()) as u64;
    let out_buf = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("out"),
        size: out_size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let staging = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("staging"),
        size: out_size,
        usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });

    let mut entries: Vec<wgpu::BindGroupEntry> = in_bufs
        .iter()
        .enumerate()
        .map(|(k, b)| wgpu::BindGroupEntry {
            binding: k as u32,
            resource: b.as_entire_binding(),
        })
        .collect();
    entries.push(wgpu::BindGroupEntry {
        binding: in_bufs.len() as u32,
        resource: out_buf.as_entire_binding(),
    });
    let bind_group = dev.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("globw-fused"),
        layout: &bgl,
        entries: &entries,
    });

    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: None,
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        let groups = n.div_ceil(256) as u32;
        pass.dispatch_workgroups(groups, 1, 1);
    }
    encoder.copy_buffer_to_buffer(&out_buf, 0, &staging, 0, out_size);
    gpu.queue.submit(Some(encoder.finish()));

    let slice = staging.slice(..);
    slice.map_async(wgpu::MapMode::Read, |_| {});
    dev.poll(wgpu::PollType::wait_indefinitely()).ok()?;
    let data = slice.get_mapped_range().ok()?;
    let out: Vec<f32> = bytemuck::cast_slice::<u8, f32>(&data).to_vec();
    drop(data);
    staging.unmap();
    Some(out)
}

// ---- resident arrays (Fase A) ---------------------------------------------
// A `nungw` array can live in GPU memory. The buffer is kept in a registry keyed
// by an id; a `GpuHandle` (held in the Value) frees it when the last reference
// drops. Data is f32 on the GPU.

/// A handle to an array resident in GPU memory. Dropping it frees the buffer.
#[derive(Debug)]
pub struct GpuHandle {
    pub id: u64,
    pub len: usize,
}
impl Drop for GpuHandle {
    fn drop(&mut self) {
        if let Ok(mut r) = registry().lock() {
            r.1.remove(&self.id);
        }
    }
}

fn registry() -> &'static Mutex<(u64, HashMap<u64, wgpu::Buffer>)> {
    static R: OnceLock<Mutex<(u64, HashMap<u64, wgpu::Buffer>)>> = OnceLock::new();
    R.get_or_init(|| Mutex::new((1, HashMap::new())))
}

/// Uploads f32 data to a resident GPU buffer; `None` if the GPU is unavailable.
pub fn upload(data: &[f32]) -> Option<Rc<GpuHandle>> {
    let gpu = ctx()?;
    let buf = gpu.device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("resident"),
        contents: bytemuck::cast_slice(data),
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
    });
    let mut r = registry().lock().ok()?;
    let id = r.0;
    r.0 += 1;
    r.1.insert(id, buf);
    Some(Rc::new(GpuHandle { id, len: data.len() }))
}

/// Downloads a resident buffer back to host f32 data.
pub fn download(h: &GpuHandle) -> Option<Vec<f32>> {
    let gpu = ctx()?;
    let dev = &gpu.device;
    let size = (h.len * std::mem::size_of::<f32>()) as u64;
    let staging = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("download"),
        size,
        usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });
    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let r = registry().lock().ok()?;
        let buf = r.1.get(&h.id)?;
        encoder.copy_buffer_to_buffer(buf, 0, &staging, 0, size);
    }
    gpu.queue.submit(Some(encoder.finish()));
    let slice = staging.slice(..);
    slice.map_async(wgpu::MapMode::Read, |_| {});
    dev.poll(wgpu::PollType::wait_indefinitely()).ok()?;
    let data = slice.get_mapped_range().ok()?;
    let out: Vec<f32> = bytemuck::cast_slice::<u8, f32>(&data).to_vec();
    drop(data);
    staging.unmap();
    Some(out)
}

/// A compute pipeline for a transpiled element-wise kernel, cached by its WGSL
/// source so a loop that reuses the same fused expression compiles it only once.
fn ew_pipeline(dev: &wgpu::Device, wgsl: &str) -> wgpu::ComputePipeline {
    static CACHE: OnceLock<Mutex<HashMap<String, wgpu::ComputePipeline>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    if let Some(p) = cache.lock().unwrap().get(wgsl) {
        return p.clone();
    }
    let module = dev.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("ew"),
        source: wgpu::ShaderSource::Wgsl(wgsl.into()),
    });
    let pipeline = dev.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("ew"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    cache.lock().unwrap().insert(wgsl.to_string(), pipeline.clone());
    pipeline
}

/// Runs a transpiled fused element-wise kernel over **resident** input arrays
/// (one storage buffer per input, bound at 0..inputs.len(), output at the end),
/// keeping the result resident. No upload or download.
pub fn run_elementwise_resident(wgsl: &str, inputs: &[&GpuHandle], n: usize) -> Option<Rc<GpuHandle>> {
    let gpu = ctx()?;
    let dev = &gpu.device;
    let pipeline = ew_pipeline(dev, wgsl);
    let bgl = pipeline.get_bind_group_layout(0);
    let out_size = (n * std::mem::size_of::<f32>()) as u64;
    let out_buf = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("ew-out"),
        size: out_size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let bind_group = {
        let r = registry().lock().ok()?;
        let mut entries: Vec<wgpu::BindGroupEntry> = Vec::with_capacity(inputs.len() + 1);
        let bufs: Vec<&wgpu::Buffer> = inputs.iter().map(|h| r.1.get(&h.id)).collect::<Option<_>>()?;
        for (k, buf) in bufs.iter().enumerate() {
            entries.push(wgpu::BindGroupEntry { binding: k as u32, resource: buf.as_entire_binding() });
        }
        entries.push(wgpu::BindGroupEntry { binding: inputs.len() as u32, resource: out_buf.as_entire_binding() });
        dev.create_bind_group(&wgpu::BindGroupDescriptor { label: Some("ew"), layout: &bgl, entries: &entries })
    };
    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor { label: None, timestamp_writes: None });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(n.div_ceil(256) as u32, 1, 1);
    }
    gpu.queue.submit(Some(encoder.finish()));
    let mut r = registry().lock().ok()?;
    let id = r.0;
    r.0 += 1;
    r.1.insert(id, out_buf);
    Some(Rc::new(GpuHandle { id, len: n }))
}

/// Sum a resident 2-D array along one axis (axis 0 -> down the rows, result
/// `cols`; axis 1 -> across the columns, result `rows`), staying resident. Used
/// for a neural network's bias gradient.
/// The reductions available on the GPU backend (both per-axis and whole-array).
#[derive(Clone, Copy, PartialEq)]
pub enum ReduceOp {
    Sum,
    Prod,
    Mean,
    Max,
    Min,
}

/// WGSL fragments for one reduction: the identity, the fold of `s` with an
/// element `v`, the fold of two partials `a`/`b`, and whether to divide by the
/// count at the end (mean).
fn reduce_parts(op: ReduceOp) -> (&'static str, &'static str, &'static str, bool) {
    match op {
        ReduceOp::Sum => ("0.0", "s + v", "a + b", false),
        ReduceOp::Prod => ("1.0", "s * v", "a * b", false),
        ReduceOp::Mean => ("0.0", "s + v", "a + b", true),
        ReduceOp::Max => ("-3.4028235e38", "max(s, v)", "max(a, b)", false),
        ReduceOp::Min => ("3.4028235e38", "min(s, v)", "min(a, b)", false),
    }
}

/// A per-axis reduction of a 2-D array (axis 0 -> down the rows, result `cols`;
/// axis 1 -> across the columns, result `rows`), staying resident. Covers the
/// bias gradient (sum, axis 0) and the softmax/batchnorm statistics (max/sum/mean
/// along an axis).
fn axis_reduce_wgsl(op: ReduceOp) -> String {
    let (init, comb, _comb2, mean) = reduce_parts(op);
    let fin0 = if mean { "s / f32(rows)" } else { "s" };
    let fin1 = if mean { "s / f32(cols)" } else { "s" };
    format!(
        "@group(0) @binding(0) var<storage, read> inp: array<f32>;
@group(0) @binding(1) var<storage, read_write> outp: array<f32>;
@group(0) @binding(2) var<uniform> dims: vec4<u32>;
@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
  let rows = dims.x;
  let cols = dims.y;
  let axis = dims.z;
  let i = gid.x;
  if (axis == 0u) {{
    if (i >= cols) {{ return; }}
    var s = {init};
    for (var r = 0u; r < rows; r = r + 1u) {{ let v = inp[r * cols + i]; s = {comb}; }}
    outp[i] = {fin0};
  }} else {{
    if (i >= rows) {{ return; }}
    var s = {init};
    for (var c = 0u; c < cols; c = c + 1u) {{ let v = inp[i * cols + c]; s = {comb}; }}
    outp[i] = {fin1};
  }}
}}
"
    )
}

/// A whole-array reduction to a single value: one workgroup of 256 threads folds
/// the array grid-stride into private partials, then a shared-memory tree folds
/// those to one result. Only one scalar is read back, so the array never leaves
/// the GPU.
fn full_reduce_wgsl(op: ReduceOp) -> String {
    let (init, comb, comb2, mean) = reduce_parts(op);
    let fin = if mean { "scratch[0] / f32(n)" } else { "scratch[0]" };
    format!(
        "@group(0) @binding(0) var<storage, read> inp: array<f32>;
@group(0) @binding(1) var<storage, read_write> outp: array<f32>;
@group(0) @binding(2) var<uniform> dims: vec4<u32>;
var<workgroup> scratch: array<f32, 256>;
@compute @workgroup_size(256)
fn main(@builtin(local_invocation_id) lid: vec3<u32>) {{
  let n = dims.x;
  let t = lid.x;
  var s = {init};
  var i = t;
  loop {{ if (i >= n) {{ break; }} let v = inp[i]; s = {comb}; i = i + 256u; }}
  scratch[t] = s;
  workgroupBarrier();
  var stride = 128u;
  loop {{
    if (stride == 0u) {{ break; }}
    if (t < stride) {{ let a = scratch[t]; let b = scratch[t + stride]; scratch[t] = {comb2}; }}
    workgroupBarrier();
    stride = stride / 2u;
  }}
  if (t == 0u) {{ outp[0] = {fin}; }}
}}
"
    )
}

pub fn axis_reduce_resident(h: &GpuHandle, rows: usize, cols: usize, axis: usize, op: ReduceOp) -> Option<Rc<GpuHandle>> {
    let gpu = ctx()?;
    let dev = &gpu.device;
    let pipeline = ew_pipeline(dev, &axis_reduce_wgsl(op));
    let bgl = pipeline.get_bind_group_layout(0);
    let out_len = if axis == 0 { cols } else { rows };
    let out_size = (out_len * std::mem::size_of::<f32>()) as u64;
    let dims: [u32; 4] = [rows as u32, cols as u32, axis as u32, 0];
    let dims_buf = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&dims),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let out_buf = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("axisreduce-out"),
        size: out_size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let bind_group = {
        let r = registry().lock().ok()?;
        let in_buf = r.1.get(&h.id)?;
        dev.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("axisreduce"),
            layout: &bgl,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: in_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: out_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: dims_buf.as_entire_binding() },
            ],
        })
    };
    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor { label: None, timestamp_writes: None });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(out_len.div_ceil(256) as u32, 1, 1);
    }
    gpu.queue.submit(Some(encoder.finish()));
    let mut r = registry().lock().ok()?;
    let id = r.0;
    r.0 += 1;
    r.1.insert(id, out_buf);
    Some(Rc::new(GpuHandle { id, len: out_len }))
}

/// Whole-array reduction of a resident array to one `f64`. The array stays in
/// VRAM; only the single result is read back.
pub fn full_reduce_resident(h: &GpuHandle, op: ReduceOp) -> Option<f64> {
    let gpu = ctx()?;
    let dev = &gpu.device;
    let pipeline = ew_pipeline(dev, &full_reduce_wgsl(op));
    let bgl = pipeline.get_bind_group_layout(0);
    let dims: [u32; 4] = [h.len as u32, 0, 0, 0];
    let dims_buf = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&dims),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let out_buf = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("reduce-out"),
        size: std::mem::size_of::<f32>() as u64,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let bind_group = {
        let r = registry().lock().ok()?;
        let in_buf = r.1.get(&h.id)?;
        dev.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("reduce"),
            layout: &bgl,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: in_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: out_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: dims_buf.as_entire_binding() },
            ],
        })
    };
    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor { label: None, timestamp_writes: None });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(1, 1, 1);
    }
    gpu.queue.submit(Some(encoder.finish()));
    // register the 1-element output so `download` can read it back, then let the
    // handle drop (freeing the buffer).
    let out_handle = {
        let mut r = registry().lock().ok()?;
        let id = r.0;
        r.0 += 1;
        r.1.insert(id, out_buf);
        Rc::new(GpuHandle { id, len: 1 })
    };
    let out = download(&out_handle)?;
    Some(*out.first()? as f64)
}

/// Matrix multiply of two **resident** arrays: `a` (rows×inner) and `b`
/// (inner×cols) already live in VRAM; the result is a new resident buffer, with
/// no upload or download. This is where resident buffers pay off.
pub fn matmul_resident(a: &GpuHandle, b: &GpuHandle, rows: usize, inner: usize, cols: usize) -> Option<Rc<GpuHandle>> {
    let gpu = ctx()?;
    let dev = &gpu.device;
    let pipeline = &gpu.matmul_pipeline;
    let bgl = pipeline.get_bind_group_layout(0);
    let out_len = rows * cols;
    let out_size = (out_len * std::mem::size_of::<f32>()) as u64;
    let dims: [u32; 4] = [rows as u32, inner as u32, cols as u32, 0];
    let dims_buf = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&dims),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let out_buf = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("matmul-out"),
        size: out_size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    // build the bind group while the registry is locked (to borrow the inputs)
    let bind_group = {
        let r = registry().lock().ok()?;
        let a_buf = r.1.get(&a.id)?;
        let b_buf = r.1.get(&b.id)?;
        dev.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("matmul-resident"),
            layout: &bgl,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: a_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: b_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: out_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 3, resource: dims_buf.as_entire_binding() },
            ],
        })
    };
    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor { label: None, timestamp_writes: None });
        pass.set_pipeline(pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(rows.div_ceil(16) as u32, cols.div_ceil(16) as u32, 1);
    }
    gpu.queue.submit(Some(encoder.finish()));
    // register the output buffer as a new resident array (no readback: stays in VRAM)
    let mut r = registry().lock().ok()?;
    let id = r.0;
    r.0 += 1;
    r.1.insert(id, out_buf);
    Some(Rc::new(GpuHandle { id, len: out_len }))
}

/// Resident GEMM with optional transpose of either operand (for `matmul_ta` /
/// `matmul_tb`): op(A) is rows×inner, op(B) is inner×cols, result rows×cols,
/// stays resident. `flags` bit0 transposes A, bit1 transposes B.
pub fn matmul_resident_t(a: &GpuHandle, b: &GpuHandle, rows: usize, inner: usize, cols: usize, flags: u32) -> Option<Rc<GpuHandle>> {
    let gpu = ctx()?;
    let dev = &gpu.device;
    let pipeline = &gpu.matmul_t_pipeline;
    let bgl = pipeline.get_bind_group_layout(0);
    let out_len = rows * cols;
    let out_size = (out_len * std::mem::size_of::<f32>()) as u64;
    let dims: [u32; 4] = [rows as u32, inner as u32, cols as u32, flags];
    let dims_buf = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&dims),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let out_buf = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("matmul-t-out"),
        size: out_size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let bind_group = {
        let r = registry().lock().ok()?;
        let a_buf = r.1.get(&a.id)?;
        let b_buf = r.1.get(&b.id)?;
        dev.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("matmul-t-resident"),
            layout: &bgl,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: a_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: b_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: out_buf.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 3, resource: dims_buf.as_entire_binding() },
            ],
        })
    };
    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor { label: None, timestamp_writes: None });
        pass.set_pipeline(pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(rows.div_ceil(16) as u32, cols.div_ceil(16) as u32, 1);
    }
    gpu.queue.submit(Some(encoder.finish()));
    let mut r = registry().lock().ok()?;
    let id = r.0;
    r.0 += 1;
    r.1.insert(id, out_buf);
    Some(Rc::new(GpuHandle { id, len: out_len }))
}

/// Benchmark probe for the "resident buffers" idea: upload `a` (n×n) and `b`
/// (n×n) ONCE, then compute `acc = acc · b` `iters` times entirely on the GPU
/// (the accumulator never leaves VRAM), and download the result ONCE. This is the
/// pattern that would win big if arrays stayed resident, since the O(n^2) upload
/// is paid once instead of every op.
pub fn matmul_chain(a: &[f32], b: &[f32], n: usize, iters: usize) -> Option<Vec<f32>> {
    let gpu = ctx()?;
    let dev = &gpu.device;
    let pipeline = &gpu.matmul_pipeline;
    let bgl = pipeline.get_bind_group_layout(0);
    let size = (n * n * std::mem::size_of::<f32>()) as u64;
    let usage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;

    let buf_a = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor { label: Some("acc"), contents: bytemuck::cast_slice(a), usage });
    let buf_b = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor { label: Some("b"), contents: bytemuck::cast_slice(b), usage: wgpu::BufferUsages::STORAGE });
    let buf_tmp = dev.create_buffer(&wgpu::BufferDescriptor { label: Some("tmp"), size, usage, mapped_at_creation: false });
    let dims: [u32; 4] = [n as u32, n as u32, n as u32, 0];
    let dims_buf = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor { label: Some("dims"), contents: bytemuck::cast_slice(&dims), usage: wgpu::BufferUsages::UNIFORM });

    let bind = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        dev.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("chain"),
            layout: &bgl,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: src.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 1, resource: buf_b.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 2, resource: dst.as_entire_binding() },
                wgpu::BindGroupEntry { binding: 3, resource: dims_buf.as_entire_binding() },
            ],
        })
    };
    let bg_a_tmp = bind(&buf_a, &buf_tmp);
    let bg_tmp_a = bind(&buf_tmp, &buf_a);

    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    let (gx, gy) = (n.div_ceil(16) as u32, n.div_ceil(16) as u32);
    let mut acc_in_a = true;
    for _ in 0..iters {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor { label: None, timestamp_writes: None });
        pass.set_pipeline(pipeline);
        pass.set_bind_group(0, if acc_in_a { &bg_a_tmp } else { &bg_tmp_a }, &[]);
        pass.dispatch_workgroups(gx, gy, 1);
        drop(pass);
        acc_in_a = !acc_in_a;
    }
    let final_buf = if acc_in_a { &buf_a } else { &buf_tmp };
    let staging = dev.create_buffer(&wgpu::BufferDescriptor { label: Some("staging"), size, usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ, mapped_at_creation: false });
    encoder.copy_buffer_to_buffer(final_buf, 0, &staging, 0, size);
    gpu.queue.submit(Some(encoder.finish()));

    let slice = staging.slice(..);
    slice.map_async(wgpu::MapMode::Read, |_| {});
    dev.poll(wgpu::PollType::wait_indefinitely()).ok()?;
    let data = slice.get_mapped_range().ok()?;
    let out: Vec<f32> = bytemuck::cast_slice::<u8, f32>(&data).to_vec();
    drop(data);
    staging.unmap();
    Some(out)
}

/// A matrix multiply on the GPU (f32): `a` is rows×inner, `b` is inner×cols,
/// both row-major; returns the rows×cols product. Unlike element-wise, matmul is
/// O(n^3) compute against O(n^2) transfer, so the GPU wins at large sizes even
/// while the inputs are re-uploaded each call. `None` on any failure -> CPU.
pub fn run_matmul(a: &[f32], b: &[f32], rows: usize, inner: usize, cols: usize) -> Option<Vec<f32>> {
    let gpu = ctx()?;
    let dev = &gpu.device;
    let pipeline = &gpu.matmul_pipeline;
    let bgl = pipeline.get_bind_group_layout(0);

    let a_buf = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("a"),
        contents: bytemuck::cast_slice(a),
        usage: wgpu::BufferUsages::STORAGE,
    });
    let b_buf = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("b"),
        contents: bytemuck::cast_slice(b),
        usage: wgpu::BufferUsages::STORAGE,
    });
    let dims: [u32; 4] = [rows as u32, inner as u32, cols as u32, 0];
    let dims_buf = dev.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: bytemuck::cast_slice(&dims),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let out_size = (rows * cols * std::mem::size_of::<f32>()) as u64;
    let out_buf = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("out"),
        size: out_size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let staging = dev.create_buffer(&wgpu::BufferDescriptor {
        label: Some("staging"),
        size: out_size,
        usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
        mapped_at_creation: false,
    });
    let bind_group = dev.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("globw-matmul"),
        layout: &bgl,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: a_buf.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 1, resource: b_buf.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 2, resource: out_buf.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 3, resource: dims_buf.as_entire_binding() },
        ],
    });

    let mut encoder = dev.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: None,
            timestamp_writes: None,
        });
        pass.set_pipeline(pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(rows.div_ceil(16) as u32, cols.div_ceil(16) as u32, 1);
    }
    encoder.copy_buffer_to_buffer(&out_buf, 0, &staging, 0, out_size);
    gpu.queue.submit(Some(encoder.finish()));

    let slice = staging.slice(..);
    slice.map_async(wgpu::MapMode::Read, |_| {});
    dev.poll(wgpu::PollType::wait_indefinitely()).ok()?;
    let data = slice.get_mapped_range().ok()?;
    let out: Vec<f32> = bytemuck::cast_slice::<u8, f32>(&data).to_vec();
    drop(data);
    staging.unmap();
    Some(out)
}

#[cfg(all(test, feature = "gpu"))]
mod chain_bench {
    use std::time::Instant;

    // Measures the "resident buffers" win: a chain acc = acc·b done `iters` times
    // on the GPU (one upload, one download) vs the same chain on the CPU BLAS.
    // b is the identity, so acc stays == a -> easy correctness check.
    #[test]
    fn resident_chain_vs_cpu() {
        let (n, iters) = (1024usize, 50usize);
        let a: Vec<f32> = (0..n * n).map(|i| ((i % 13) as f32) * 0.5).collect();
        let mut b = vec![0f32; n * n];
        for i in 0..n {
            b[i * n + i] = 1.0;
        }
        // warm up the device (one-time init) so it is out of the timing
        let _ = super::matmul_chain(&a, &b, 64, 1);

        let t = Instant::now();
        let gpu_res = super::matmul_chain(&a, &b, n, iters).expect("gpu chain");
        let gpu_s = t.elapsed().as_secs_f64();
        let max_err = gpu_res.iter().zip(&a).map(|(x, y)| (x - y).abs()).fold(0.0f32, f32::max);
        assert!(max_err < 1e-3, "gpu chain incorrect, max_err = {max_err}");

        let a64: Vec<f64> = a.iter().map(|&x| x as f64).collect();
        let b64: Vec<f64> = b.iter().map(|&x| x as f64).collect();
        let mut acc = a64.clone();
        let mut out = vec![0f64; n * n];
        let t = Instant::now();
        for _ in 0..iters {
            crate::library::matmul_into(&mut out, &acc, &b64, n, n, n);
            std::mem::swap(&mut acc, &mut out);
        }
        let cpu_s = t.elapsed().as_secs_f64();

        eprintln!(
            "\n[resident chain n={n} iters={iters}]  GPU {gpu_s:.3}s   CPU-BLAS {cpu_s:.3}s   speedup {:.1}x\n",
            cpu_s / gpu_s
        );
    }
}
